          title: "手写一台 60 行的分词器：训练、编码、解码、回验全跑通",
          code: "# 一台最小的分词器：训练合并规则 → 编码 → 解码，三步闭环\nclass MiniTokenizer:\n    def __init__(self, specials):\n        self.merges = []                 # 按学习顺序存放的合并规则，顺序就是优先级\n        self.vocab = {}                  # token -> id\n        self.specials = list(specials)\n        for t in self.specials:\n            self._add(t)                 # 特殊符号先占住低 id\n\n    def _add(self, token):\n        if token not in self.vocab:\n            self.vocab[token] = len(self.vocab)      # 新 token 只能追加在末尾\n        return self.vocab[token]\n\n    def _merge(self, chars, left, right):\n        out, i = [], 0\n        while i < len(chars):\n            if i + 1 < len(chars) and chars[i] == left and chars[i + 1] == right:\n                out.append(left + right)             # 这一对焊成一块\n                i += 2\n            else:\n                out.append(chars[i])\n                i += 1\n        return tuple(out)\n\n    def train(self, corpus):\n        for word, _ in corpus:\n            for ch in word:\n                self._add(ch)                        # 语料里出现过的字先登记\n        data = [(tuple(w), n) for w, n in corpus]\n        while True:\n            stats = {}\n            for chars, n in data:\n                for i in range(len(chars) - 1):\n                    pair = (chars[i], chars[i + 1])\n                    stats[pair] = stats.get(pair, 0) + n\n            if not stats:\n                break\n            left, right = max(stats, key=stats.get)\n            data = [(self._merge(chars, left, right), n) for chars, n in data]\n            self.merges.append((left, right))\n            self._add(left + right)\n        for i in range(256):\n            self._add('0x%02X' % i)                  # 256 个字节 token：字节兜底的退路\n        return [l + r for l, r in self.merges]\n\n    def encode(self, text):\n        toks = list(text)\n        for left, right in self.merges:               # 按学习顺序应用，顺序 = 优先级\n            toks = list(self._merge(tuple(toks), left, right))\n        ids, fallback = [], 0\n        for t in toks:\n            if t in self.vocab:\n                ids.append(self.vocab[t])\n            else:\n                for b in t.encode('utf-8'):           # 查不到 → 拆成 UTF-8 字节\n                    ids.append(self._add('0x%02X' % b))\n                    fallback += 1\n        return ids, fallback\n\n    def decode(self, ids):\n        inv = {v: k for k, v in self.vocab.items()}\n        out, buf = [], bytearray()\n        for i in ids:\n            t = inv[i]\n            if len(t) == 4 and t.startswith('0x'):\n                buf.append(int(t[2:], 16))            # 字节先攒着，攒够一个字符再解\n            else:\n                if buf:\n                    out.append(bytes(buf).decode('utf-8'))\n                    buf.clear()\n                out.append(t)\n        if buf:\n            out.append(bytes(buf).decode('utf-8'))\n        return ''.join(out)\n\n\ncorpus = [('我们', 5), ('学习', 4), ('中文分词', 3), ('我爱', 2)]\ntok = MiniTokenizer(['[PAD]', '[UNK]', '[BOS]', '[EOS]'])\nrules = tok.train(corpus)\nprint('学到的合并规则', len(rules), '条：', ' '.join(rules))\nprint('词表大小', len(tok.vocab), '= 特殊符号 4 + 语料用到的字 9 + 合并出来的块 6 + 字节 256')\nprint('抽几个 id：[BOS]', tok.vocab['[BOS]'], '，我', tok.vocab['我'], '，我们', tok.vocab['我们'])\n\nfor s in ['我们学习中文分词', '机器猫', '我们学习中文，也爱机器猫']:\n    ids, fallback = tok.encode(s)\n    back = tok.decode(ids)\n    print(s, '→', len(s), '个字符 /', len(ids), '个 token（字节兜底', fallback, '个），',\n          round(len(ids) / len(s), 2), 'token/字符，解码还原：', back == s)\n\nbefore = len(tok.vocab)\ntok._add('[USR]')\nprint('追加一个新符号：[BOS] 仍是', tok.vocab['[BOS]'], '，[USR] 拿到 id', tok.vocab['[USR]'], '= 追加前的词表大小', before)\nprint('若把新符号插在 [BOS] 前：从 id', tok.vocab['[BOS]'], '起的', len(tok.vocab) - tok.vocab['[BOS]'], '个 token 都要往后挪一位')\n"
